function lever(F1, d1, d2){
  F1=+F1; d1=+d1; d2=+d2;
  if([F1,d1,d2].some(function(v){return isNaN(v)||v<=0;})) return {error:'力与力臂须为正'};
  var F2 = F1*d1/d2;
  var type = d2>d1 ? '省力杠杆（F₂<F₁）' : (d2<d1 ? '费力杠杆（F₂>F₁）' : '等臂（F₂=F₁）');
  return {F2:Math.round(F2*100)/100, F1:F1, d1:d1, d2:d2, type:type};
}
var EXPORTS={lever:lever};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LeverForgePure = EXPORTS; }
